CREATE TABLE "Users" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "first_name" varchar(50),
  "last_name" varchar(50),
  "email" varchar(100) UNIQUE,
  "phone" varchar(20) UNIQUE,
  "password_hash" varchar(255),
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "Roles" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "role_name" varchar(50)
);

CREATE TABLE "UserRoles" (
  "user_id" int,
  "role_id" int,
  "branch_id" int,
  PRIMARY KEY ("user_id", "role_id")
);

CREATE TABLE "Branches" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100),
  "address" text,
  "latitude" decimal(10,8),
  "longitude" decimal(11,8),
  "working_hours" varchar(100),
  "is_active" boolean DEFAULT true
);

CREATE TABLE "Categories" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50),
  "display_order" int
);

CREATE TABLE "Products" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_id" int,
  "name" varchar(100),
  "description" text,
  "image_url" varchar(255),
  "allergens" text,
  "is_active" boolean DEFAULT true
);

CREATE TABLE "BranchProducts" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "branch_id" int,
  "product_id" int,
  "is_in_stock" boolean DEFAULT true,
  "price" decimal(10,2)
);

CREATE TABLE "ProductOptionGroups" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int,
  "name" varchar(50),
  "is_required" boolean DEFAULT false,
  "min_selectable" int DEFAULT 1,
  "max_selectable" int DEFAULT 1
);

CREATE TABLE "ProductOptions" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "group_id" int,
  "name" varchar(50),
  "base_additional_price" decimal(10,2) DEFAULT 0
);

CREATE TABLE "BranchOptionPrices" (
  "branch_id" int,
  "option_id" int,
  "additional_price" decimal(10,2),
  PRIMARY KEY ("branch_id", "option_id")
);

CREATE TABLE "Carts" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
  "branch_id" int,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "CartItems" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cart_id" int,
  "product_id" int,
  "quantity" int DEFAULT 1
);

CREATE TABLE "CartItemOptions" (
  "cart_item_id" int,
  "option_id" int,
  PRIMARY KEY ("cart_item_id", "option_id")
);

CREATE TABLE "Orders" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_number" varchar(20) UNIQUE,
  "user_id" int,
  "branch_id" int,
  "total_amount" decimal(10,2),
  "discount_amount" decimal(10,2) DEFAULT 0,
  "final_amount" decimal(10,2),
  "status" varchar(30),
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "OrderItems" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" int,
  "product_id" int,
  "quantity" int,
  "unit_price" decimal(10,2)
);

CREATE TABLE "OrderItemOptions" (
  "order_item_id" int,
  "option_id" int,
  "additional_price" decimal(10,2),
  PRIMARY KEY ("order_item_id", "option_id")
);

CREATE TABLE "Payments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" int,
  "payment_method" varchar(30),
  "payment_status" varchar(30),
  "transaction_id" varchar(100),
  "created_at" timestamp
);

CREATE TABLE "Campaigns" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar(150),
  "description" text,
  "campaign_type" varchar(50),
  "priority" int DEFAULT 0,
  "can_combine" boolean DEFAULT false,
  "min_cart_amount" decimal(10,2) DEFAULT 0,
  "start_date" timestamp,
  "end_date" timestamp,
  "is_active" boolean DEFAULT true
);

CREATE TABLE "CampaignBranches" (
  "campaign_id" int,
  "branch_id" int,
  PRIMARY KEY ("campaign_id", "branch_id")
);

CREATE TABLE "Coupons" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "campaign_id" int,
  "coupon_code" varchar(20) UNIQUE,
  "user_id" int,
  "usage_limit" int DEFAULT 1,
  "used_count" int DEFAULT 0,
  "is_active" boolean DEFAULT true
);

CREATE TABLE "CouponRedemptions" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "coupon_id" int,
  "order_id" int,
  "user_id" int,
  "redeemed_at" timestamp DEFAULT (now())
);

CREATE TABLE "LoyaltyAccounts" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
  "total_points" int DEFAULT 0,
  "current_stamps" int DEFAULT 0,
  "updated_at" timestamp
);

CREATE TABLE "LoyaltyTransactions" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "loyalty_account_id" int,
  "order_id" int,
  "transaction_type" varchar(30),
  "points_changed" int DEFAULT 0,
  "stamps_changed" int DEFAULT 0,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "RewardQRs" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
  "reward_type" varchar(50),
  "qr_code_token" varchar(100) UNIQUE,
  "is_used" boolean DEFAULT false,
  "expires_at" timestamp,
  "created_at" timestamp
);

CREATE TABLE "AuditLogs" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
  "action" varchar(100),
  "table_name" varchar(50),
  "record_id" int,
  "old_values" text,
  "new_values" text,
  "ip_address" varchar(45),
  "created_at" timestamp DEFAULT (now())
);

CREATE UNIQUE INDEX ON "BranchProducts" ("branch_id", "product_id");

